import {products,keys,read,write,money,priceFor,escapeHTML as esc} from './data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const heart='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M20.4 4.6a5.3 5.3 0 0 0-7.5 0L12 5.5l-.9-.9a5.3 5.3 0 0 0-7.5 7.5L12 20.5l8.4-8.4a5.3 5.3 0 0 0 0-7.5Z"/></svg>';
let catalog=products(),cart=read(keys.cart,[]),favorites=read('amago.favorites.v1',[]);
if(!Array.isArray(cart))cart=[];if(!Array.isArray(favorites))favorites=[];
let family='todos',selectedSize=50,selectedQuantity=1,shipping=null,coupon=false,payment='pix',quizStep=0,quizAnswers=[],toastTimer,observer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800)}
function persist(key,value){const ok=write(key,value);if(!ok)toast('Não foi possível salvar. Verifique o espaço do navegador.');return ok}
function syncCart(){const used={};cart=cart.filter(i=>{const p=catalog.find(p=>p.id===i.id);if(!p||!(p.sizes||[50,100]).includes(i.size)||!Number.isInteger(i.qty)||i.qty<1)return false;i.qty=Math.min(i.qty,Math.max(0,p.stock-(used[i.id]||0)));used[i.id]=(used[i.id]||0)+i.qty;return i.qty>0})}
function saveCart(){syncCart();persist(keys.cart,cart);const n=cart.reduce((n,i)=>n+i.qty,0);$('.bag-count').textContent=n;$('.bag-toggle').setAttribute('aria-label',`Abrir sacola, ${n} itens`)}
const cartCount=id=>cart.filter(i=>i.id===id).reduce((n,i)=>n+i.qty,0);
const subtotal=()=>cart.reduce((total,item)=>{const p=catalog.find(p=>p.id===item.id);return total+(p?priceFor(p,item.size)*item.qty:0)},0);
const shippingCost=()=>shipping?(subtotal()>=299?0:shipping.price):0;
function totals(){const base=subtotal(),discount=Math.round(base*(coupon?.1:0)*100)/100,pix=payment==='pix'?Math.round((base-discount)*.05*100)/100:0;return {base,discount,pix,freight:shippingCost(),total:base-discount-pix+shippingCost()}}
function showDialog(id){$$('dialog[open]').forEach(d=>d.close());const d=$(id);d.showModal();d.scrollTop=0;document.body.classList.add('modal-open')}
function closeDialog(d){d.close();if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open')}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(d.id==='product-dialog'&&location.hash.startsWith('#perfume/'))history.replaceState(null,'','#colecao')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
$$('.dialog-close').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));
function card(p,index=0){const favored=favorites.includes(p.id);return `<article class="product-card reveal" style="--delay:${index%4*70}ms"><div class="product-photo-wrap"><button class="product-image" data-product="${esc(p.id)}" style="background:${esc(p.color)}" aria-label="Conhecer ${esc(p.name)}"><span class="product-badge">${esc(p.badge)}</span><img src="${esc(p.image)}" alt="${esc(p.name)} — ${esc(p.brand||'Âmago')}, ${esc(p.concentration||'eau de parfum')}" width="1000" height="1000" loading="lazy"><span class="product-open" aria-hidden="true">＋</span></button><button class="favorite-toggle ${favored?'is-favorite':''}" data-favorite="${esc(p.id)}" aria-label="${favored?'Remover':'Salvar'} ${esc(p.name)} ${favored?'dos':'nos'} favoritos" aria-pressed="${favored}">${heart}</button></div><div class="product-meta"><span>${esc(p.brand||p.family)}</span><span>${p.stock>0?(p.sizes?.[0]||50)+' ml':'Esgotado'}</span></div><h3><button data-product="${esc(p.id)}">${esc(p.name)}</button></h3><p class="product-notes">${esc(p.notes)}</p><p class="product-price">${money(p.price)} <span>ou 3x de ${money(p.price/3)}</span></p></article>`}
function renderProducts(){let list=catalog.filter(p=>family==='todos'||p.family===family);const audience=$('#audience').value;if(audience!=='todos')list=list.filter(p=>p.audience===audience);list=list.filter(p=>p.price<=Number($('#price-range').value));const order=$('#sort').value;if(order==='price-asc')list.sort((a,b)=>a.price-b.price);if(order==='price-desc')list.sort((a,b)=>b.price-a.price);if(order==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#product-grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty-state"><h3>Ainda não encontramos.</h3><p>Tente outra família ou amplie a faixa de preço.</p><button class="button button-wine" data-reset-filters>Limpar filtros</button></div>';$('.filter[data-filter="todos"] sup').textContent=String(catalog.length).padStart(2,'0');$('#result-count').textContent=`${list.length} ${list.length===1?'perfume encontrado':'perfumes encontrados'}`;revealElements()}
$$('.filter').forEach(b=>b.addEventListener('click',()=>{family=b.dataset.filter;$$('.filter').forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',String(f===b))});renderProducts()}));
$('#sort').onchange=renderProducts;$('#audience').onchange=renderProducts;$('#price-range').oninput=e=>{$('#price-value').textContent=money(Number(e.target.value));renderProducts()};
function resetFilters(){family='todos';$('#audience').value='todos';$('#price-range').value=3000;$('#price-value').textContent=money(3000);$('#sort').value='curadoria';$$('.filter').forEach(f=>{const active=f.dataset.filter==='todos';f.classList.toggle('active',active);f.setAttribute('aria-pressed',String(active))});renderProducts()}
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product)openProduct(product.dataset.product);const fav=e.target.closest('[data-favorite]');if(fav)toggleFavorite(fav.dataset.favorite);if(e.target.closest('[data-reset-filters]'))resetFilters();if(e.target.closest('[data-quiz]'))startQuiz();if(e.target.closest('[data-continue]')){$$('dialog[open]').forEach(closeDialog);$('#colecao').scrollIntoView({behavior:'smooth'})}});
function openProduct(id){const p=catalog.find(p=>p.id===id);if(!p)return;selectedSize=p.sizes?.[0]||50;selectedQuantity=1;$('#product-detail').innerHTML=`<div class="detail-image" style="background:${esc(p.color)}"><img src="${esc(p.image)}" alt="Frasco de ${esc(p.name)}" width="1000" height="1000"><span>${esc(p.brand||'ÂMAGO')} — ${esc(p.concentration||'EAU DE PARFUM')}</span></div><div class="detail-copy"><p class="eyebrow">${esc(p.brand||'ÂMAGO')} · ${esc(p.family)}</p><h2 id="detail-title">${esc(p.name)}</h2><p class="detail-mood">${esc(p.mood)}</p><p class="detail-description">${esc(p.description)}</p><div class="detail-price"><strong id="detail-price">${money(p.price)}</strong><span id="detail-installments">ou 3x de ${money(p.price/3)} sem juros</span></div><fieldset class="sizes"><legend>O seu tamanho</legend>${(p.sizes||[50,100]).map((size,i)=>`<label><input type="radio" name="size" value="${size}" ${i===0?'checked':''}><span>${size} ml</span></label>`).join('')}</fieldset><div class="purchase-row"><div class="quantity-control"><button id="detail-minus" aria-label="Diminuir quantidade">−</button><output id="detail-quantity" aria-label="Quantidade">1</output><button id="detail-plus" aria-label="Aumentar quantidade">+</button></div><button class="button button-wine" id="add-to-bag" ${p.stock<1?'disabled':''}>${p.stock>0?'Adicionar à sacola':'Indisponível'}</button></div><p class="detail-stock">${p.stock>0?`${p.stock} unidades no estoque demonstrativo`:'Receberemos novidades em breve.'}</p><div class="olfactory-notes"><p class="eyebrow">A HISTÓRIA NA PELE</p><div><span>Notas principais</span><p>${esc(p.notes)}</p></div><div><span>Concentração</span><p>${esc(p.concentration)}</p></div><div><span>Família</span><p>${esc(p.family)}</p></div></div><p class="product-disclaimer">Produto real · preço e estoque ilustrativos.${p.source?` <a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Conheça na marca</a>`:''}</p></div>`;$('#product-dialog').setAttribute('aria-labelledby','detail-title');showDialog('#product-dialog');history.replaceState(null,'',`#perfume/${encodeURIComponent(id)}`);$$('input[name="size"]').forEach(r=>r.onchange=()=>{selectedSize=Number(r.value);$('#detail-price').textContent=money(priceFor(p,selectedSize));$('#detail-installments').textContent=`ou 3x de ${money(priceFor(p,selectedSize)/3)} sem juros`});$('#detail-minus').onclick=()=>{$('#detail-quantity').textContent=selectedQuantity=Math.max(1,selectedQuantity-1)};$('#detail-plus').onclick=()=>{if(selectedQuantity+cartCount(id)>=p.stock)return toast('Você chegou ao estoque disponível.');$('#detail-quantity').textContent=++selectedQuantity};$('#add-to-bag').onclick=()=>{if(addToCart(id,selectedSize,selectedQuantity)){showCart();toast(`${p.name} adicionado à sua sacola.`)}}}
function addToCart(id,size=50,qty=1){catalog=products();const p=catalog.find(p=>p.id===id);if(!p||!(p.sizes||[50,100]).includes(size)||!Number.isInteger(qty)||qty<1)return false;if(cartCount(id)+qty>p.stock){toast('Essa quantidade não está disponível no estoque.');return false}const item=cart.find(i=>i.id===id&&i.size===size);if(item)item.qty+=qty;else cart.push({id,size,qty});saveCart();return true}
function toggleFavorite(id){if(!catalog.some(p=>p.id===id))return;const exists=favorites.includes(id);favorites=exists?favorites.filter(i=>i!==id):[...favorites,id];persist('amago.favorites.v1',favorites);$$(`[data-favorite="${CSS.escape(id)}"]`).forEach(b=>{b.classList.toggle('is-favorite',!exists);b.setAttribute('aria-pressed',String(!exists));b.setAttribute('aria-label',`${exists?'Salvar':'Remover'} ${catalog.find(p=>p.id===id).name} ${exists?'nos':'dos'} favoritos`)});$('.favorites-count').textContent=favorites.filter(id=>catalog.some(p=>p.id===id)).length;if($('#favorites-dialog').open)renderFavorites();toast(exists?'Perfume removido dos favoritos.':'Um favorito para reencontrar depois.')}
function renderFavorites(){const list=catalog.filter(p=>favorites.includes(p.id));$('#favorites-content').innerHTML=list.length?`<div class="favorites-grid">${list.map(card).join('')}</div>`:'<div class="empty-state"><span class="empty-symbol">♡</span><h3>Guarde um encontro.</h3><p>Toque no coração de um perfume<br>para encontrá-lo aqui depois.</p><button class="button button-wine" data-continue>Explorar perfumes</button></div>';revealElements()}
$('.favorites-header').onclick=()=>{renderFavorites();showDialog('#favorites-dialog')};
function cartLine(item,index){const p=catalog.find(p=>p.id===item.id);return `<article class="cart-item"><button class="cart-item-image" data-product="${esc(p.id)}" aria-label="Ver ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="160" height="160"></button><div class="cart-item-details"><span class="eyebrow">${esc(p.brand||p.family)}</span><h3>${esc(p.name)}</h3><p>${item.size} ml · ${money(priceFor(p,item.size))}</p><div class="cart-item-bottom"><div class="quantity-control"><button data-cart-change="${index}" data-delta="-1" aria-label="Diminuir ${esc(p.name)}">−</button><output>${item.qty}</output><button data-cart-change="${index}" data-delta="1" aria-label="Aumentar ${esc(p.name)}">+</button></div><button class="remove-item" data-remove="${index}">Remover</button></div></div><strong>${money(priceFor(p,item.size)*item.qty)}</strong></article>`}
function showCart(){catalog=products();syncCart();saveCart();renderCart();showDialog('#cart-dialog')}
function renderCart(){if(!cart.length){$('#cart-content').innerHTML='<div class="empty-state"><span class="empty-symbol">a.</span><h3>Sua próxima história<br>ainda está por aqui.</h3><p>Encontre um perfume para chamar de seu.</p><button class="button button-wine" data-continue>Explorar a coleção</button></div>';return}const base=subtotal(),remaining=Math.max(0,299-base);$('#cart-content').innerHTML=`<p class="shipping-progress-text">${remaining?`Faltam ${money(remaining)} para o frete grátis.`:'Seu encontro ganhou frete grátis.'}</p><div class="shipping-progress"><span style="width:${Math.min(base/299*100,100)}%"></span></div><div class="cart-items">${cart.map(cartLine).join('')}</div><form id="shipping-form" class="shipping-form"><label for="shipping-cep">Simule a entrega</label><div><input id="shipping-cep" placeholder="Seu CEP" aria-label="CEP para simular entrega" inputmode="numeric" pattern="[0-9]{5}-?[0-9]{3}" maxlength="9" value="${shipping?esc(shipping.cep):''}" required><button type="submit">Calcular</button></div><p class="shipping-result" id="shipping-result" aria-live="polite">${shipping?shippingLabel():'Valores e prazos fictícios para demonstração.'}</p></form><form id="coupon-form" class="coupon-form"><label for="coupon-input">Tem um convite especial?</label><div><input id="coupon-input" placeholder="Cupom: PRIMEIRO10" value="${coupon?'PRIMEIRO10':''}" aria-label="Cupom de desconto"><button type="submit">${coupon?'Remover':'Aplicar'}</button></div><p id="coupon-feedback" aria-live="polite">${coupon?'10% de desconto aplicado.':''}</p></form><div class="cart-summary"><p><span>Subtotal</span><strong>${money(base)}</strong></p>${coupon?`<p><span>Convite PRIMEIRO10</span><span>− ${money(base*.1)}</span></p>`:''}<p><span>Entrega</span><span>${shipping?shippingCost()?money(shippingCost()):'Por nossa conta':'A calcular'}</span></p><p class="summary-total"><span>Total</span><strong>${money(base*(coupon?.9:1)+shippingCost())}</strong></p><button class="button button-wine" id="start-checkout">Continuar para a compra</button><button class="continue-shopping" data-continue>Continuar descobrindo</button><p class="checkout-note">Loja demonstrativa. Nenhuma cobrança será realizada.</p></div>`;$$('[data-cart-change]').forEach(b=>b.onclick=()=>{const i=cart[Number(b.dataset.cartChange)],delta=Number(b.dataset.delta),p=catalog.find(p=>p.id===i.id);if(delta>0&&cartCount(i.id)>=p.stock)return toast('Estoque máximo atingido.');i.qty+=delta;cart=cart.filter(i=>i.qty>0);saveCart();renderCart()});$$('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);saveCart();renderCart()});$('#shipping-form').onsubmit=e=>{e.preventDefault();calculateShipping($('#shipping-cep').value);renderCart()};$('#shipping-cep').oninput=()=>{shipping=null;$('#shipping-result').textContent='Calcule novamente para este CEP.'};$('#coupon-form').onsubmit=e=>{e.preventDefault();if(coupon){coupon=false;renderCart();return}if($('#coupon-input').value.trim().toUpperCase()==='PRIMEIRO10'){coupon=true;renderCart();toast('Convite aceito: 10% de desconto.')}else $('#coupon-feedback').textContent='Cupom não encontrado. Experimente PRIMEIRO10.'};$('#start-checkout').textContent='Ver minha sacola';$('#start-checkout').onclick=()=>{location.href='carrinho.html'}}
function calculateShipping(value){const digits=value.replace(/\D/g,'');if(digits.length!==8||/^0{8}$/.test(digits)){toast('Informe um CEP com 8 dígitos válido para a simulação.');return false}const region=Number(digits.slice(0,2));shipping={cep:`${digits.slice(0,5)}-${digits.slice(5)}`,price:region<40?14.9:region<80?22.9:29.9,days:region<40?'3 a 5':region<80?'5 a 8':'7 a 12'};return true}
function shippingLabel(){return `Entrega padrão: ${shipping.days} dias úteis · ${shippingCost()?money(shippingCost()):'grátis'}. Simulação.`}
$('.bag-toggle').onclick=()=>{location.href='carrinho.html'};
function startCheckout(){if(!cart.length)return;payment='pix';$('#checkout-content').innerHTML=`<p class="eyebrow">UM NOVO ENCONTRO</p><h2>Quase na sua <em>pele.</em></h2><p class="demo-banner">Esta é uma compra de demonstração. Use dados fictícios. Nenhum pagamento será processado.</p><form id="checkout-form"><div class="checkout-columns"><div><h3>01. Quem vai receber?</h3><div class="form-grid"><label>Nome de demonstração<input name="name" required minlength="2" maxlength="80" placeholder="Ex.: Maria Exemplo" autocomplete="off"></label><label>E-mail de demonstração<input name="email" type="email" required placeholder="maria@example.com" autocomplete="off"></label><label>CEP<input name="cep" inputmode="numeric" pattern="[0-9]{5}-?[0-9]{3}" maxlength="9" required value="${shipping?esc(shipping.cep):''}" placeholder="00000-000"></label><label>Cidade<input name="city" required maxlength="80" placeholder="Sua cidade" autocomplete="off"></label><label class="full-field">Endereço de demonstração<input name="address" required maxlength="150" placeholder="Rua Exemplo, 123" autocomplete="off"></label></div><p class="checkout-delivery" id="checkout-delivery">${shipping?shippingLabel():'Digite o CEP para simular a entrega.'}</p><h3>02. Como prefere pagar?</h3><fieldset class="payment-options"><legend class="sr-only">Forma de pagamento demonstrativa</legend><label><input type="radio" name="payment" value="pix" checked><span><strong>Pix</strong><small>5% de desconto</small></span></label><label><input type="radio" name="payment" value="card"><span><strong>Cartão de crédito</strong><small>Até 3x sem juros</small></span></label></fieldset><div id="payment-description" class="payment-description">Pix simulado: a confirmação é apenas visual. Nenhuma chave será gerada.</div></div><aside class="order-summary"><h3>Seu encontro</h3>${cart.map(i=>{const p=catalog.find(p=>p.id===i.id);return `<div class="order-mini"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="60" height="70"><div><strong>${esc(p.name)}</strong><span>${i.size} ml · ${i.qty} ${i.qty===1?'unidade':'unidades'}</span></div><span>${money(priceFor(p,i.size)*i.qty)}</span></div>`}).join('')}<div id="checkout-totals"></div><button class="button button-wine" type="submit">Concluir pedido de teste</button><p class="checkout-note">Seu pedido ficará salvo apenas neste navegador.</p></aside></div></form>`;showDialog('#checkout-dialog');renderCheckoutTotals();const form=$('#checkout-form');form.elements.cep.oninput=()=>{shipping=null;renderCheckoutTotals();$('#checkout-delivery').textContent='Digite o CEP completo para atualizar a simulação.'};form.elements.cep.onchange=()=>{if(calculateShipping(form.elements.cep.value)){$('#checkout-delivery').textContent=shippingLabel();renderCheckoutTotals()}};$$('input[name="payment"]').forEach(r=>r.onchange=()=>{payment=r.value;$('#payment-description').textContent=payment==='pix'?'Pix simulado: a confirmação é apenas visual. Nenhuma chave será gerada.':'Cartão demonstrativo •••• 4242. Não solicitamos dados reais de cartão.';renderCheckoutTotals()});form.onsubmit=completeOrder}
function completeOrder(e){e.preventDefault();const form=e.currentTarget;if(!calculateShipping(form.elements.cep.value)||!cart.length)return;const current=products();for(const i of cart){const p=current.find(p=>p.id===i.id);if(!p||cartCount(i.id)>p.stock){toast('O estoque mudou. Revise sua sacola.');catalog=current;showCart();return}}catalog=current;const total=totals(),order={id:'AM-'+Date.now().toString(36).toUpperCase(),date:new Date().toISOString(),name:form.elements.name.value.trim(),email:form.elements.email.value.trim(),city:form.elements.city.value.trim(),cep:shipping.cep,payment,total:Math.round(total.total*100)/100,items:cart.map(i=>({...i,name:current.find(p=>p.id===i.id).name,price:priceFor(current.find(p=>p.id===i.id),i.size)})),status:'Demonstração concluída'};const updated=current.map(p=>({...p,stock:p.stock-cartCount(p.id)})),previousOrders=read(keys.orders,[]);if(!persist(keys.products,updated))return;if(!persist(keys.orders,[order,...previousOrders])){persist(keys.products,current);return}catalog=updated;cart=[];shipping=null;coupon=false;saveCart();renderProducts();$('#checkout-content').innerHTML=`<div class="order-success"><span class="success-seal">a.</span><p class="eyebrow">PEDIDO ${esc(order.id)}</p><h2>Um novo capítulo.<br>Uma nova <em>memória.</em></h2><p>Pronto, ${esc(order.name.split(' ')[0])}.<br>Seu pedido demonstrativo de <strong>${money(order.total)}</strong> foi registrado.</p><div class="success-info">Nenhuma cobrança ou entrega será realizada.<br>Você pode conferir este pedido no painel de gestão.</div><button class="button button-wine" data-continue>Continuar descobrindo</button><a href="admin.html#pedidos" class="text-link">Ver pedido na gestão</a></div>`}
function renderCheckoutTotals(){if(!$('#checkout-totals'))return;const t=totals();$('#checkout-totals').innerHTML=`<p><span>Subtotal</span><span>${money(t.base)}</span></p>${t.discount?`<p><span>PRIMEIRO10</span><span>− ${money(t.discount)}</span></p>`:''}${t.pix?`<p><span>5% no Pix</span><span>− ${money(t.pix)}</span></p>`:''}<p><span>Frete simulado</span><span>${shipping?t.freight?money(t.freight):'Grátis':'A calcular'}</span></p><p class="summary-total"><span>Total</span><strong>${money(t.total)}</strong></p>${payment==='card'?`<small>3x de ${money(t.total/3)} sem juros</small>`:''}`}
const normalize=text=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function renderSearch(){const term=normalize($('#search-input').value.trim()),list=catalog.filter(p=>normalize([p.name,p.brand,p.notes,p.family,p.description].join(' ')).includes(term));$('#search-results').innerHTML=`<p class="search-result-label">${term?`${list.length} encontros para a sua busca`:'Comece por um perfume ou uma nota olfativa'}</p>`+(list.length?list.map(p=>`<button class="search-result" data-product="${esc(p.id)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="65" height="75"><span><small>${esc(p.brand||p.family)}</small><strong>${esc(p.name)}</strong><span>${esc(p.notes)}</span></span><b>${money(p.price)}</b></button>`).join(''):'<div class="empty-state"><h3>Novos caminhos?</h3><p>Tente buscar por “floral”, “baunilha” ou pelo nome da marca.</p></div>')}
