$('#header-search-form').onsubmit=e=>{e.preventDefault();$('#search-input').value=$('#header-search-input').value;renderSearch();showDialog('#search-dialog');$('#search-input').focus()};
$$('[data-nav-filter]').forEach(b=>b.addEventListener('click',()=>{resetFilters();$('#audience').value=b.dataset.navFilter;renderProducts()}));
$$('[data-nav-family]').forEach(b=>b.addEventListener('click',()=>{resetFilters();$(`.filter[data-filter="${b.dataset.navFamily}"]`).click()}));
$('.mobile-menu').onclick=()=>{const open=$('.main-nav').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(open))};$$('.main-nav a').forEach(a=>a.onclick=()=>{$('.main-nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false')});
const quizQuestions=[{title:'O que desperta você?',subtitle:'Comece por uma sensação. Não existe resposta errada.',options:[['Floral','Um jardim depois da chuva','Flores, delicadeza e presença.'],['Cítrico','O sol entrando pela janela','Frescor, energia e leveza.'],['Amadeirado','O silêncio de uma floresta','Madeiras, textura e profundidade.'],['Ambarado','Uma noite que não termina','Calor, especiarias e mistério.']]},{title:'Para qual momento?',subtitle:'O perfume acompanha a sua versão de cada dia.',options:[['dia','Para todos os dias','Da primeira reunião ao café da tarde.'],['noite','Para uma ocasião especial','Jantares, encontros e novas histórias.'],['sempre','Para usar sem regras','A vontade é o melhor motivo.']]},{title:'Como quer ser lembrado?',subtitle:'Uma última pista para encontrar seu próximo encontro.',options:[['Feminino','Por uma assinatura feminina','Flores e contrastes marcantes.'],['Masculino','Por uma assinatura masculina','Frescor e madeiras envolventes.'],['todos','Pelo que me faz sentir bem','Quero descobrir sem limitar.']]}];
function startQuiz(){quizStep=0;quizAnswers=[];renderQuiz();showDialog('#quiz-dialog')}
function renderQuiz(){const q=quizQuestions[quizStep];$('#quiz-content').innerHTML=`<p class="eyebrow">SEU PERFUME, DO SEU JEITO · ${quizStep+1} / 3</p><div class="quiz-progress"><span style="width:${(quizStep+1)/3*100}%"></span></div><h2>${q.title}</h2><p class="quiz-subtitle">${q.subtitle}</p><div class="quiz-options">${q.options.map((o,i)=>`<button data-answer="${i}"><span class="quiz-option-number">0${i+1}</span><span><strong>${o[1]}</strong><small>${o[2]}</small></span><span class="quiz-radio"></span></button>`).join('')}</div>${quizStep?'<button class="quiz-back">Voltar uma sensação</button>':''}`;$$('[data-answer]').forEach(b=>b.onclick=()=>{quizAnswers[quizStep]=q.options[Number(b.dataset.answer)][0];quizStep++;if(quizStep<3)renderQuiz();else showQuizResults()});if($('.quiz-back'))$('.quiz-back').onclick=()=>{quizStep--;renderQuiz()}}
function showQuizResults(){const ranked=catalog.filter(p=>p.stock>0).map(p=>({p,score:(p.family===quizAnswers[0]?4:0)+(p.audience===quizAnswers[2]?3:0)+(quizAnswers[1]==='noite'&&p.intensity>=4?1:0)+(quizAnswers[1]==='dia'&&p.intensity<4?1:0)})).sort((a,b)=>b.score-a.score).slice(0,2);$('#quiz-content').innerHTML=`<p class="eyebrow">DOIS ENCONTROS PARA COMEÇAR</p><h2>Talvez seja <em>por aqui.</em></h2><p class="quiz-subtitle">Uma seleção a partir das suas preferências. A melhor descoberta ainda acontece na sua pele.</p><div class="quiz-results">${ranked.map(({p},i)=>card(p,i)).join('')}</div><button class="quiz-back" id="restart-quiz">Descobrir outros caminhos</button>`;$('#restart-quiz').onclick=startQuiz;revealElements()}
const info={contato:['Vamos conversar.','A Âmago é uma loja conceito. Os canais de atendimento serão conectados na versão final. Por enquanto, explore o catálogo, experimente o guia de fragrâncias e faça um pedido de teste.'],entregas:['Cada encontro tem seu tempo.','Nesta demonstração, o frete é calculado por uma tabela fictícia a partir do CEP. Compras a partir de R$ 299 recebem frete grátis simulado. Os prazos apresentados não são cotações de transportadoras.','As políticas reais de entrega, troca e devolução serão definidas com a loja antes do lançamento.'],privacidade:['Sua experiência, com cuidado.','Esta loja modelo armazena sacola, favoritos, catálogo e pedidos de teste apenas neste navegador. O painel de gestão é demonstrativo e não possui autenticação.','Não insira informações pessoais reais. Não coletamos dados de cartão, e nenhum pedido ou e-mail é enviado.'],instagram:['Um universo em construção.','O perfil oficial da loja será conectado aqui na versão de lançamento. Por enquanto, o botão é apenas demonstrativo.'],pinterest:['Referências que ficam.','O Pinterest da marca será conectado na versão final. Explore o caderno de sensações para conhecer a direção desta curadoria.']};
$$('[data-info]').forEach(b=>b.onclick=()=>{const [title,...paragraphs]=info[b.dataset.info];$('#info-content').innerHTML=`<p class="eyebrow">UNIVERSO ÂMAGO</p><h2>${title}</h2>${paragraphs.map(p=>`<p>${p}</p>`).join('')}`;showDialog('#info-dialog')});
$('#read-article').onclick=()=>{$('#info-content').innerHTML='<p class="eyebrow">CADERNO DE SENSAÇÕES · Nº 01</p><h2>Um perfume.<br>Mil maneiras de sentir.</h2><p>A descoberta de uma fragrância pode começar por uma memória: uma flor no caminho, uma casca de laranja, a madeira de uma casa antiga. Use essas lembranças como ponto de partida.</p><h3>Primeiro, encontre uma família.</h3><p>Os florais colocam as flores em primeiro plano. Os cítricos exploram o frescor. Os amadeirados trazem textura e profundidade. Os ambarados se aproximam de sensações quentes e envolventes. Muitos perfumes passeiam por mais de uma família.</p><h3>Dê tempo ao encontro.</h3><p>Experimente na pele e perceba como a fragrância se apresenta ao longo do dia. A impressão inicial é só o começo. O perfume que conquista você pode ser o que continua interessante algumas horas depois.</p><h3>Escolha por você.</h3><p>As categorias são um guia, não uma regra. Um perfume pode acompanhar um momento, uma estação ou simplesmente a vontade de sentir algo diferente.</p><button class="button button-wine" data-quiz>Descobrir minha fragrância</button>';showDialog('#info-dialog')};
function revealElements(){const elements=$$('.reveal:not(.is-visible)');if(matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver'in window)){elements.forEach(el=>el.classList.add('is-visible'));return}if(!observer)observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -25px 0px'});elements.forEach(el=>observer.observe(el))}
$$('.section-heading,.intro-line,.manifesto-label,.manifesto-copy,.journal-feature,.service-notes>div,.footer-top,.footer-wordmark,.scent-editorial,.discovery').forEach(el=>el.classList.add('reveal'));document.body.classList.add('motion-ready');
let scrollScheduled=false;window.addEventListener('scroll',()=>{if(scrollScheduled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;scrollScheduled=true;requestAnimationFrame(()=>{const photo=$('.hero-photo');if(photo&&scrollY<1100)photo.style.setProperty('--scroll',Math.min(scrollY*.07,45)+'px');scrollScheduled=false})},{passive:true});
window.addEventListener('storage',e=>{if(e.key===keys.products){catalog=products();syncCart();saveCart();renderProducts();if($('#cart-dialog').open)renderCart()}if(e.key===keys.cart){cart=read(keys.cart,[]);syncCart();$('.bag-count').textContent=cart.reduce((n,i)=>n+i.qty,0);if($('#cart-dialog').open)renderCart()}if(e.key==='amago.favorites.v1'){favorites=read(e.key,[]);renderProducts();$('.favorites-count').textContent=favorites.length;if($('#favorites-dialog').open)renderFavorites()}});
syncCart();saveCart();renderProducts();$('.favorites-count').textContent=favorites.length;if(location.hash.startsWith('#perfume/'))openProduct(decodeURIComponent(location.hash.slice(9)));
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'search_perfumes',title:'Buscar perfumes',description:'Consulta o catálogo demonstrativo por nome, marca ou notas, sem alterar estado.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(typeof input?.query!=='string')throw new Error('query deve ser texto');const query=normalize(input.query);return catalog.filter(p=>normalize(`${p.name} ${p.brand} ${p.notes} ${p.family}`).includes(query)).map(p=>({id:p.id,name:p.name,price:p.price,stock:p.stock}))}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
